(7441679, 1176737, 96751, '<td valign="top">You have created an image I thought was by the venerable <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/user_id/100393.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/user_id/100393.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/user_id/100393.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=100393" rel="nofollow" target="_blank">Paul</a>!  Congrats on the HM.</td>', 'You have created an image I thought was by the venerable  Paul!  Congrats on the HM.', '2016-03-07 10:26:17.000000', NULL, 0),
